import { useRef, useState } from "react";

export function SignupForm({ onSubmit }) {
  const emailRef = useRef(null);
  const nameRef = useRef(null);
  const [errors, setErrors] = useState({});

  function handleSubmit(event) {
    event.preventDefault();
    const data = new FormData(event.currentTarget);
    const next = {};
    if (!String(data.get("name")).trim()) next.name = "Enter your name.";
    if (!String(data.get("email")).includes("@")) next.email = "Enter a valid email.";
    setErrors(next);
    if (next.name) nameRef.current.focus();          // in the handler: fine.
    else if (next.email) emailRef.current.focus();
    else onSubmit(data);
  }

  return (
    <form onSubmit={handleSubmit} noValidate>
      <label>Name <input name="name" ref={nameRef} aria-invalid={Boolean(errors.name)} /></label>
      {errors.name && <p role="alert">{errors.name}</p>}
      <label>Email <input name="email" ref={emailRef} aria-invalid={Boolean(errors.email)} /></label>
      {errors.email && <p role="alert">{errors.email}</p>}
      <button type="submit">Sign up</button>
    </form>
  );
}
